const listBackingPaths = `-- name: ListBackingPaths :many
SELECT path FROM vm_memory_backings WHERE deleted_at IS NULL ORDER BY path
`

func (q *Queries) ListBackingPaths(ctx context.Context) ([]string, error) {
	rows, err := q.db.QueryContext(ctx, listBackingPaths)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var path string
		if err := rows.Scan(&path); err != nil {
			return nil, err
		}
		items = append(items, path)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

